#include <stdio.h>

int main() {
	int total = 0;
	int count = 10;
	for (int i = 0; i < count; i++) {
		total = total + i;
	}
	printf("Total: %d\n", total);
	return 0;
}

#include <stdio.h>

int main() {
	int a, b;
	printf("Enter two numbers: ");
	scanf("%d %d", &a, &b);
	if (a > b) {
		printf("Larger: %d\n", a);
	} else {
		printf("Larger: %d\n", b);
	}
	return 0;
}

#include <stdio.h>

int main() {
	int n = 1;
	int factorial = 1;
	while (n <= 5) {
		factorial = factorial * n;
		n++;
	}
	printf("Factorial of 5 = %d\n", factorial);
	if (factorial > 100) {
		printf("Large result\n");
	}
	return 0;
}

#include <stdio.h>

int sumArray(int arr[], int size) {
	int sum = 0;
	for (int i = 0; i < size; i++) {
		sum += arr[i];
	}
	return sum;
}

int main() {
	int nums[5] = {10, 20, 30, 40, 50};
	printf("Sum: %d\n", sumArray(nums, 5));
	return 0;
}

#include <stdio.h>

struct Point {
	int x;
	int y;
};

int main() {
	struct Point p1;
	p1.x = 10;
	p1.y = 20;
	printf("Point: %d, %d\n", p1.x, p1.y);
	return 0;
}

#include <stdio.h>

void swap(int *a, int *b) {
	int temp = *a;
	*a = *b;
	*b = temp;
}

int main() {
	int x = 5, y = 10;
	swap(&x, &y);
	printf("x = %d, y = %d\n", x, y);
	return 0;
}

#include <stdio.h>

int main() {
	for (int i = 1; i <= 3; i++) {
		for (int j = 1; j <= 3; j++) {
			printf("%d ", i * j);
		}
		printf("\n");
	}
	return 0;
}

