#include <stdio.h>
int main() {
	int age = 20;
	int hasID = 1;
	int isVIP = 0;

	if ((age >= 18 && hasID == 1) || isVIP == 1) {
		printf("Access Granted!\n");
	}
	else if (age < 18 && !hasID) {
		printf("Access Denied: Minor without ID.\n");
	}
	else {
		printf("Access Denied.\n");
	}
	return 0;
}

#include <stdio.h>
int main() {
	int userChoice;
	do {
		printf("\n--- MENU ---\n");
		printf("1. Play Game\n");
		printf("2. Settings\n");
		printf("3. Exit\n");
		printf("Enter your choice (1-3): ");
	} while (userChoice < 1 || userChoice > 3);
	printf("Valid choice selected: %d\n", userChoice);
	return 0;
}
